// dma_buffer.h —— 抽象数据类型接口
typedef struct DmaBuffer DmaBuffer;

// 初始化：关联DMA通道、环形缓冲区大小和回调
DmaBuffer* DmaBuffer_Create(DmaChannel* chan,
                            uint8_t* ring_buf,
                            size_t ring_size,
                            DmaBuffer_Callback cb);

// 开始DMA单次传输（触发一次采样或一帧接收）
int DmaBuffer_Start(DmaBuffer* db);

// 检查是否有新数据到达（非阻塞）
bool DmaBuffer_HasData(DmaBuffer* db);

// 拷贝一份有效数据到用户缓冲区（环形拷贝）
size_t DmaBuffer_Consume(DmaBuffer* db, void* out_buf, size_t max);

// 返回当前已接收但未消费的字节数
size_t DmaBuffer_GetAvailable(DmaBuffer* db);

// 清理资源
void DmaBuffer_Destroy(DmaBuffer* db);

#include "stm32f4xx_ll_dma.h"
#include "stm32f4xx_ll_usart.h"

#define RX_BUF_SIZE     64
#define RX_BUFFERS      2
typedef struct {
    uint8_t buf[RX_BUF_SIZE * RX_BUFFERS];
    volatile uint16_t dma_half_idx;  // 半传中断时的索引（0-63）
    volatile uint16_t cpu_consume_idx; // CPU消费偏移
    volatile bool half_done;         // 半传标记
} UartRxState;

static UartRxState rx_state = {0};

// DMA半传输中断：其中一个64字节缓冲区已满
static void DMA1_Stream6_IRQHandler(void) {
    if (LL_DMA_IsEnabledIRQ(DMA1, Stream6, IT_HT)) {
        LL_DMA_ClearHTIF(DMA1, Stream6);
        rx_state.half_done = true;
        rx_state.dma_half_idx = RX_BUF_SIZE; // 第二个区开始写入
    }
}

// 启动UART+DMA双缓冲连续接收
void UartRx_Start(void) {
    // 1. 清空状态
    memset(rx_state.buf, 0, sizeof(rx_state.buf));
    rx_state.cpu_consume_idx = 0;
    rx_state.half_done = false;

    // 2. 配置UART
    LL_USART_SetBaudRate(USART2, SystemClock_GetFreq(), 115200);
    LL_USART_SetFrameFormat(USART2, 8, USART_WORDLENGTH_8B,
                           USART_PARITY_NONE, 1);
    LL_USART_EnableIT_PE | IT_FRAMING | IT_ORE, USART2);

    // 3. 配置DMA双缓冲区（非循环模式，用手动切换）
    LL_DMA_ConfigChannel(DMA1, Stream6, USART2_DR_Address,
                         LL_DMA_DIR_PERIPH_TO_MEMORY,
                         LL_DMA_PERIPH_DATA_BYTE,
                         LL_DMA_MEMORY_DATA_BYTE,
                         LL_DMA_MODE_CIRCULAR, // DMA自动回绕指针
                         LL_DMA_PRIORITY_HIGH);

    // 4. 设置传输长度（一次性传128字节，两个缓冲区）
    LL_DMA_SetTransferLength(DMA1, Stream6, RX_BUF_SIZE * RX_BUFFERS);

    // 5. 使能DMA和UART
    LL_DMA_EnableChannel(DMA1, Stream6);
    LL_USART_EnableDMAReqRx(USART2);
    LL_USART_Enable(USART2);
}

// 在主轮询中检查并拷贝数据
void UartRx_Process(void) {
    if (rx_state.half_done) {
        // DMA刚刚写完第二个64字节区（offset 64-127）
        // 这里可以异步标记有数据，由主线程处理
        rx_state.half_done = false;
    }

    // 计算可读字节：当前DMA位置减去CPU消费位置
    uint16_t dma_pos = rx_state.dma_half_idx + RX_BUF_SIZE;
    uint16_t available = (dma_pos - rx_state.cpu_consume_idx) % 
                         (RX_BUF_SIZE * RX_BUFFERS);
    if (available > 0) {
        memcpy(read_buf, rx_state.buf + rx_state.cpu_consume_idx, available);
        rx_state.cpu_consume_idx += available;
    }
}

// BAD: 危险的双缓冲实现——缺少同步保护
uint8_t* get_current_buf() {
    return (rx_state.dma_idx < RX_BUF_SIZE) ? 
           rx_state.buf[0] : rx_state.buf[1];
}

void process_data() {
    uint8_t* buf = get_current_buf();
    // DMA可能在读取期间切换缓冲区！
    consume(buf, RX_BUF_SIZE);
}

// GOOD：使用序列号保护
uint8_t* get_safe_buf(uint16_t seq_expected) {
    if (rx_state.seq == seq_expected) return rx_state.buf[rx_state.cur_idx];
    return NULL; // 数据无效，等待重新同步
}

// idma_strategy.h —— 策略接口
typedef struct IDmaStrategy IDmaStrategy;

typedef struct {
    void (*init)(IDmaStrategy* self, Udma_context* ctx);
    void (*start)(IDmaStrategy* self);
    void (*cleanup)(IDmaStrategy* self);
} IDmaStrategyVtbl;

struct IDmaStrategy {
    const IDmaStrategyVtbl* vtbl;
    Udma_context* ctx;
    uint16_t buffer_len;
};

// adc_dma_strategy.c —— ADC专用策略
static void adc_init(IDmaStrategy* self, Udma_context* ctx) {
    self->ctx = ctx;
    self->buffer_len = ADC_BUFFER_SZ;
    // 仅配置ADC相关的DMA通道和循环模式
    LL_ADC_ConfigDMA(self->ctx->adc_instance, 
                     LL_DMA_PERIPH_DIRECTION_PERIPH_TO_MEMORY,
                     LL_DMA_MODE_CIRCULAR,
                     LL_DMA_PRIORITY_HIGH);
}

static void adc_start(IDmaStrategy* self) {
    ADC_StartConversion(self->ctx->adc_instance);
}

static const IDmaStrategyVtbl ADC_STRATEGY_VTABLE = {
    .init = adc_init,
    .start = adc_start,
    .cleanup = NULL
};

static ADC_DmaStrategy adc_strat = {
    .vtbl = &ADC_STRATEGY_VTABLE,
    .ctx = NULL,
    .buffer_len = 0
};

// uart_dma_strategy.c —— UART专用策略
static void uart_init(IDmaStrategy* self, Udma_context* ctx) {
    self->ctx = ctx;
    self->buffer_len = UART_RX_BUF;
    LL_UART_ConfigDMA(self->ctx->uart_instance,
                      LL_DMA_DIR_PERIPH_TO_MEMORY,
                      LL_DMA_MODE_CIRCULAR,
                      LL_DMA_PRIORITY_MEDIUM);
}

static void uart_start(IDmaStrategy* self) {
    LL_UART_EnableDMAReqRx(self->ctx->uart_instance);
}

const IDmaStrategy VTABLE_UART = {
    .init = uart_init,
    .start = uart_start,
    .cleanup = NULL
};

// main.c —— 统一入口
void System_Init(Udma_context* ctx) {
    // 根据运行时选择策略：ADC或UART
    IDmaStrategy* dma_dev = (use_adc) ? 
        (IDmaStrategy*)&adc_strat : (IDmaStrategy*)&uart_strat;
    dma_dev->vtbl->init(dma_dev, ctx);
    dma_dev->vtbl->start(dma_dev);
}
